SELECT * FROM (SELECT 'CI:' || instruction_id event_id, material_id case_id, 'Cutting Instruction Released' activity, released_at timestamp FROM cutting_finishing_instruction UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Split Cutting Completed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='SC' UNION ALL SELECT 'DIM:' || p.plate_material_id event_id, m.material_id case_id, 'Dimensional Inspection Completed' activity, p.dimension_inspected_at timestamp FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no WHERE p.dimension_inspected_at IS NOT NULL) ORDER BY case_id,timestamp,event_id;
